using System;using System.IO;using System.Text;
class SteamInstallRepairTests {
 static void A(bool value,string message){if(!value)throw new Exception(message);}
 static void Reject(Action action){bool refused=false;try{action();}catch{refused=true;}A(refused,"expected refusal");}
 static void Exe(string root,ushort machine){Directory.CreateDirectory(root);var data=new byte[256];data[0]=0x4d;data[1]=0x5a;BitConverter.GetBytes(128).CopyTo(data,0x3c);BitConverter.GetBytes(0x4550).CopyTo(data,128);BitConverter.GetBytes(machine).CopyTo(data,132);File.WriteAllBytes(Path.Combine(root,"steam.exe"),data);}
 static string Fixture(string work,string name){string root=Path.Combine(work,name);Exe(root,0x14c);File.WriteAllText(Path.Combine(root,"tier0_s.dll"),"original x86");File.WriteAllText(Path.Combine(root,"tier0_s64.dll"),"original x64");Directory.CreateDirectory(Path.Combine(root,"steamapps/common/Test"));File.WriteAllText(Path.Combine(root,"steamapps/common/Test/tier0_s.dll"),"game");Directory.CreateDirectory(Path.Combine(root,"userdata"));File.WriteAllText(Path.Combine(root,"userdata/account"),"keep");File.WriteAllText(Path.Combine(root,"steam.cfg"),"unchanged");return root;}
 static void Main(){string work=Path.Combine(Path.GetTempPath(),"fixer-install-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(work);try{
 string root=Fixture(work,"normal Unicode 游戏");int checks=0;var result=SteamInstallRepair.Prepare(root,false,()=>checks++,s=>{});A(result.Moved==2&&checks==2,"idle checked before preparing and moving");A(!File.Exists(Path.Combine(root,"tier0_s.dll"))&&!File.Exists(Path.Combine(root,"tier0_s64.dll")),"only root bootstrap DLLs moved");A(File.ReadAllText(Path.Combine(result.Backup,"tier0_s.dll"))=="original x86"&&File.ReadAllText(Path.Combine(result.Backup,"tier0_s64.dll"))=="original x64","original bytes recoverable");A(File.ReadAllText(Path.Combine(result.Backup,"backup.json")).Contains(Core.Hash(Path.Combine(result.Backup,"tier0_s.dll"))),"backup hashes recorded");A(File.ReadAllText(result.Launcher)==SteamInstallRepair.LauncherText,"fixed parameter launcher");A(File.ReadAllText(Path.Combine(root,"steamapps/common/Test/tier0_s.dll"))=="game"&&File.ReadAllText(Path.Combine(root,"userdata/account"))=="keep"&&File.ReadAllText(Path.Combine(root,"steam.cfg"))=="unchanged","game, account and bootstrap config retained");int backups=Directory.GetDirectories(Path.Combine(root,"LegacySteamFixer-InstallRepair")).Length;var retry=SteamInstallRepair.Prepare(root,false,()=>{},s=>{});A(retry.Moved==0&&retry.Backup==null&&Directory.GetDirectories(Path.Combine(root,"LegacySteamFixer-InstallRepair")).Length==backups,"repeat with missing DLLs creates no duplicate backup");
 string active=Fixture(work,"active");Reject(()=>SteamInstallRepair.Prepare(active,false,()=>{throw new Exception("still running");},s=>{}));A(File.Exists(Path.Combine(active,"tier0_s.dll"))&&!File.Exists(Path.Combine(active,SteamInstallRepair.LauncherName)),"running refusal changes nothing");
 string rollback=Fixture(work,"rollback");Reject(()=>SteamInstallRepair.Prepare(rollback,false,()=>{},s=>{throw new Exception("injected failure after move");}));A(File.ReadAllText(Path.Combine(rollback,"tier0_s.dll"))=="original x86"&&File.ReadAllText(Path.Combine(rollback,"tier0_s64.dll"))=="original x64","partial failure rolls back");
 string unknown=Fixture(work,"unrelated launcher");File.WriteAllText(Path.Combine(unknown,SteamInstallRepair.LauncherName),"user script");Reject(()=>SteamInstallRepair.Prepare(unknown,false,()=>{},s=>{}));A(File.ReadAllText(Path.Combine(unknown,SteamInstallRepair.LauncherName))=="user script"&&File.Exists(Path.Combine(unknown,"tier0_s.dll")),"unknown existing launcher retained");
 string x64=Fixture(work,"wrong architecture");Exe(x64,0x8664);Reject(()=>SteamInstallRepair.Prepare(x64,false,()=>{},s=>{}));A(File.Exists(Path.Combine(x64,"tier0_s.dll")),"x64-on-x86 refused before writes");Reject(()=>SteamInstallRepair.Validate(work,false));
 Console.WriteLine("PASS: first-install backup, hashes, root-only scope, fixed launcher, retry, active-client refusal, rollback, unknown script and architecture refusal. No live Steam/UAC or Windows download tested.");
 }finally{Directory.Delete(work,true);}}
}
